using System;

namespace Apogee.Design
{
    /// <summary>
    /// Represents a specific, measurable objective success criterion generated by the Mission Composer.
    /// Used by mission evaluation and post-mission reporting.
    /// Complies with GDD §5.5, §10.5, and §19.3.
    /// </summary>
    public sealed class MissionSuccessCriterion
    {
        public string ObjectiveId { get; }
        public string CriterionType { get; }
        public double Threshold { get; }
        public string Description { get; }

        public MissionSuccessCriterion(string objectiveId, string criterionType, double threshold, string description = null)
        {
            ObjectiveId = objectiveId ?? string.Empty;
            CriterionType = criterionType ?? "general";
            Threshold = threshold;
            Description = !string.IsNullOrWhiteSpace(description)
                ? description
                : BuildDefaultDescription(CriterionType, Threshold);
        }

        private static string BuildDefaultDescription(string criterionType, double threshold)
        {
            switch (criterionType?.ToLowerInvariant())
            {
                case "data-delivered-gb":
                    return $"En az {threshold:0.#} GB bilim verisi Dünya'ya aktarılmalı.";
                case "operation-days":
                    return $"En az {threshold:0} gün operasyonel veri toplanmalı.";
                case "coverage-days":
                    return $"En az {threshold:0} gün kesintisiz yörünge/iletişim kapsaması sağlanmalı.";
                case "sample-returned":
                    return "Numune güvenli şekilde Dünya'ya ulaştırılmalı.";
                case "sample-prepared":
                    return "Yüzeyden toplanan numuneler mühürlenmeli ve hazır edilmeli.";
                default:
                    return $"Hedef eşiği ({threshold:0.#}) başarıyla sağlanmalı.";
            }
        }

        public override string ToString() => $"[{CriterionType} >= {Threshold:0.#}] {Description}";
    }
}
